class Solution {
public:
    string capitalizeTitle(string title) {
        stringstream in(title);
        string word, res;
        while (in >> word) {
            for (char &c : word) c = tolower(c);
            if (word.size() > 2) word[0] = toupper(word[0]);
            if (!res.empty()) res += ' ';
            res += word;
        }
        return res;
    }
};

