class Solution:
    def capitalizeTitle(self, title: str) -> str:
        chars = list(title)
        n = len(chars)
        i = 0
        while i < n:
            j = i
            while j < n and chars[j] != ' ':
                chars[j] = chars[j].lower()
                j += 1
            if j - i > 2:
                chars[i] = chars[i].upper()
            i = j + 1
        return ''.join(chars)

