class Solution {
    public String capitalizeTitle(String title) {
        char[] cs = title.toCharArray();
        int n = cs.length;
        for (int i = 0; i < n; ) {
            int j = i;
            while (j < n && cs[j] != ' ') {
                cs[j] = Character.toLowerCase(cs[j]);
                j++;
            }
            if (j - i > 2) cs[i] = Character.toUpperCase(cs[i]);
            i = j + 1;
        }
        return new String(cs);
    }
};

