var capitalizeTitle = function(title) {
    const cs = title.split('');
    const n = cs.length;
    for (let i = 0; i < n; ) {
        let j = i;
        while (j < n && cs[j] !== ' ') {
            cs[j] = cs[j].toLowerCase();
            j++;
        }
        if (j - i > 2) cs[i] = cs[i].toUpperCase();
        i = j + 1;
